package com.kh.back.chatbot.service;

import com.kh.back.common.exception.ApiException;
import java.util.Map;
import static java.util.Map.entry;
import org.springframework.http.HttpStatus;

/** Reviewed public guidance. Reading these answers never calls an external model. */
public final class ChatGuideAnswers {
    public record Guide(String question, String answer) {}

    private static final Map<String, Guide> ANSWERS = Map.ofEntries(
        entry("service-overview", new Guide("서비스를 어떻게 이용하나요?", "CreditComPass에서는 첫 차 취향 테스트, 재무 진단, 차량 찾기와 차량 비교를 이용할 수 있어요. 취향부터 알고 싶다면 로그인 후 마이페이지에서 취향 테스트를 시작해 보세요. 예산을 먼저 살펴보고 싶다면 재무 진단을, 관심 있는 차가 있다면 차량 찾기와 비교를 이용하면 돼요.")),
        entry("taste-save", new Guide("취향 테스트 결과는 어떻게 저장하나요?", "로그인 후 취향 테스트의 8개 질문에 답하고 결과 화면에서 저장 버튼을 눌러 주세요. 이미 현재 결과를 저장했다면 저장 완료로 표시되고 중복 저장은 할 수 없어요. 다시 테스트한 결과를 저장할 때는 기존 취향을 덮어쓸지 확인하며, 결과만 확인하고 저장하지 않으면 기존 취향은 유지돼요.")),
        entry("vehicle-compare", new Guide("차량을 비교하려면 어떻게 하나요?", "추천 차량이나 차량 상세에서 비교할 차량을 최대 3대까지 추가한 뒤 상단의 차량 비교 메뉴를 열어 보세요. 같은 기준으로 계산한 구매비용, 유지비와 재무 적합도를 나란히 살펴볼 수 있어요. 내 조건을 반영하고 싶다면 재무 정보를 입력하고, 화면에 표시된 선수금·할부 기간·금리·주행거리 등 계산 기준도 함께 확인해 주세요.")),
        entry("sedan-suv", new Guide("세단과 SUV는 어떻게 다른가요?", "세단은 대체로 차체가 낮고 객실과 트렁크가 나뉜 형태예요. SUV는 대체로 차체와 좌석 위치가 높고 뒤쪽 적재 공간이 객실과 연결되어 있어요. 다만 승차감, 짐 공간, 연비는 차종마다 다르므로 실제 차량의 제원도 함께 비교하는 게 좋아요.")),
        entry("hybrid-electric", new Guide("하이브리드는 무엇인가요?", "하이브리드(HEV)는 엔진과 전기모터를 함께 사용하는 차예요. 일반 하이브리드는 외부 충전기 대신 주행과 감속 과정에서 배터리를 충전해요. 전기차는 구동용 엔진 없이 전기모터로 달리며 외부 충전이 필요하다는 차이가 있어요.")),
        entry("MPV", new Guide("MPV는 어떤 차인가요?", "MPV는 Multi-Purpose Vehicle의 약자로, 여러 사람이 타거나 짐을 싣는 등 공간 활용을 중시한 다목적 차량이에요. 기아 카니발 같은 미니밴을 떠올리면 이해하기 쉬워요. SUV도 사람과 짐을 실을 수 있지만, MPV는 좌석 배치와 승하차 등 실내 활용에 더 초점을 둔 분류예요. 좌석 수와 슬라이딩 도어 유무는 모델마다 달라요.")),
        entry("SUV", new Guide("SUV는 무슨 뜻인가요?", "SUV는 Sport Utility Vehicle의 약자로, 일상 이동과 다양한 활동에 활용하도록 만든 차량 분류예요. 대체로 세단보다 차체와 좌석 위치가 높고 적재 공간을 유연하게 활용할 수 있어요. SUV라고 모두 사륜구동이거나 험로 주행에 적합한 것은 아니므로 해당 모델의 사양을 확인해 주세요.")),
        entry("MIDSIZE_SUV", new Guide("중형 SUV는 어떤 차인가요?", "MIDSIZE_SUV는 중형 SUV를 뜻해요. 이 사이트에서는 소형·준중형 SUV보다 큰 차급을 구분하는 표현으로 사용하며, 기아 쏘렌토 같은 차를 떠올리면 이해하기 쉬워요. 대형 SUV보다 보통 작지만 차급의 경계는 제조사와 분류 기준에 따라 달라요. 좌석 수와 실제 크기는 각 차량의 제원을 확인해 주세요.")),
        entry("SUBCOMPACT_SUV", new Guide("소형 SUV는 무슨 뜻인가요?", "SUBCOMPACT_SUV는 소형 SUV를 뜻해요. SUV 중 비교적 작은 차급으로, 큰 SUV보다 도심 이동과 주차 부담을 줄이고 싶은 경우 살펴볼 수 있어요. 실내와 짐 공간은 모델별 차이가 크고, 소형이라는 분류가 같은 크기를 보장하지는 않아요.")),
        entry("COMPACT_SUV", new Guide("준중형 SUV는 무슨 뜻인가요?", "COMPACT_SUV는 준중형 SUV를 뜻해요. 이 사이트에서 소형과 중형 SUV 사이의 차급을 구분하는 표현이에요. 차체 크기와 실내 활용의 균형을 살펴볼 수 있지만, 실제 공간과 좌석 수는 모델마다 확인해야 해요.")),
        entry("LARGE_SUV", new Guide("대형 SUV는 무슨 뜻인가요?", "LARGE_SUV는 대형 SUV를 뜻해요. SUV 중 비교적 큰 차급으로, 여러 사람이 타거나 짐을 실을 공간을 중요하게 볼 때 살펴볼 수 있어요. 모든 대형 SUV가 같은 좌석 수를 갖는 것은 아니며, 주차 공간과 차량의 실제 크기도 함께 확인하는 게 좋아요.")),
        entry("COMPACT_SEDAN", new Guide("준중형 세단은 무슨 뜻인가요?", "COMPACT_SEDAN은 준중형 세단을 뜻해요. 이 사이트에서는 중형 세단보다 작은 차급을 구분하는 표현이에요. 세단은 보통 객실과 트렁크가 나뉜 형태이며, 실제 차체 크기와 뒷좌석 공간은 모델마다 달라요.")),
        entry("MIDSIZE_SEDAN", new Guide("중형 세단은 무슨 뜻인가요?", "MIDSIZE_SEDAN은 중형 세단을 뜻해요. 이 사이트에서는 준중형과 대형 세단 사이의 차급을 나타내요. 일상 이동과 동승자 공간을 함께 비교해 볼 수 있으며, 차급만으로 승차감이나 연비를 판단하기보다 개별 차량의 제원을 확인해 주세요.")),
        entry("FULLSIZE_SEDAN", new Guide("대형 세단은 무슨 뜻인가요?", "FULLSIZE_SEDAN은 대형 세단을 뜻해요. 세단 중 비교적 큰 차급으로, 실내 공간과 편의성을 중시할 때 살펴볼 수 있어요. 차체가 큰 만큼 주차 환경도 함께 고려하고, 실제 공간과 편의 사양은 트림별로 확인해 주세요.")),
        entry("MINI", new Guide("경차는 무슨 뜻인가요?", "경차는 국내에서 배기량과 차체 크기 등 법정 기준을 충족하는 작은 자동차 분류예요. 단순히 작은 차라고 모두 경차는 아니며, 소형차와도 구분돼요. 경차 관련 혜택은 적용 요건과 시기에 따라 다르므로 실제 구매 시 별도로 확인해 주세요.")),
        entry("SEDAN", new Guide("세단은 무슨 뜻인가요?", "세단은 대체로 엔진 공간, 사람이 타는 객실, 트렁크가 구분된 승용차 형태예요. SUV보다 차체와 좌석 위치가 낮은 경우가 많아요. 다만 차체 형태만으로 승차감이나 연비가 정해지는 것은 아니므로 개별 차량도 함께 비교해 주세요.")),
        entry("HYBRID", new Guide("하이브리드는 무슨 뜻인가요?", "하이브리드(HEV)는 엔진과 전기모터를 함께 사용하는 차예요. 일반 하이브리드는 외부 충전 없이 주행과 감속 과정에서 배터리를 충전해요. 외부 충전이 가능한 PHEV, 엔진 없이 전기모터로 달리는 전기차와 구분돼요.")),
        entry("MILD_HYBRID", new Guide("마일드 하이브리드는 무슨 뜻인가요?", "마일드 하이브리드는 작은 전기모터 등이 엔진의 출발과 가속을 보조하는 방식이에요. 일반 하이브리드와 달리 전기모터만으로 주행하는 기능은 대체로 제한적이에요. 구체적인 작동 방식은 제조사와 모델에 따라 달라요.")),
        entry("PHEV", new Guide("PHEV와 일반 하이브리드는 다른가요?", "PHEV는 플러그인 하이브리드로, 엔진과 전기모터를 함께 쓰면서 외부 충전기로 배터리를 충전할 수 있는 차예요. 일반 하이브리드보다 전기로만 달릴 수 있는 거리가 보통 길지만 모델과 주행 조건에 따라 달라요. 일반 하이브리드는 외부 충전이 필요 없고, PHEV는 충전 환경도 함께 고려하는 게 좋아요.")),
        entry("ELECTRIC", new Guide("전기차는 무슨 뜻인가요?", "전기차(EV·BEV)는 배터리에 저장한 전기로 모터를 돌려 달리는 차예요. 구동용 내연기관 없이 주행하므로 휘발유나 경유 대신 외부 충전이 필요해요. 한 번 충전으로 달릴 수 있는 거리는 차량, 기온, 속도 등에 따라 달라요.")),
        entry("GASOLINE", new Guide("가솔린은 무슨 뜻인가요?", "가솔린은 휘발유를 뜻해요. 가솔린 차량은 휘발유를 연료로 사용하는 엔진이 있는 차예요. 디젤·LPG와 연료가 다르므로 주유할 때는 반드시 차량에 지정된 연료를 확인해야 해요.")),
        entry("DIESEL", new Guide("디젤은 무슨 뜻인가요?", "디젤은 경유를 연료로 사용하는 엔진 방식을 뜻해요. 가솔린 차량과 사용하는 연료 및 엔진의 작동 방식이 달라요. 연비, 소음, 배출가스 관리와 정비 조건은 모델과 사용 환경에 따라 다르므로 함께 비교해 주세요.")),
        entry("LPG", new Guide("LPG는 무슨 뜻인가요?", "LPG는 액화석유가스로, 자동차에서는 전용 연료와 연료 공급 장치를 사용하는 방식이에요. 가솔린이나 디젤과 다른 연료이며 LPG 충전소에서 충전해요. 이용할 수 있는 충전소와 차량별 연비, 적재 공간 등을 함께 확인해 주세요.")),
        entry("RUNNING_COST", new Guide("예상 월 유지비는 무슨 뜻인가요?", "예상 월 유지비는 차량을 이용하면서 한 달에 들 것으로 추산한 비용이에요. 연료비, 보험료, 세금, 정비비 등이 관련되지만 화면의 계산에 포함되는 항목과 조건을 확인해야 해요. 실제 비용은 주행거리, 운전 습관, 보험 조건 등에 따라 달라지며 차량 할부금이 자동으로 포함된다고 볼 수는 없어요.")),
        entry("EFFICIENCY", new Guide("복합연비는 무슨 뜻인가요?", "복합연비는 정해진 시험 기준에 따라 도심과 고속도로 주행을 함께 반영한 연비예요. km/L는 연료 1리터로 갈 수 있는 거리로, 같은 조건이면 숫자가 클수록 적은 연료로 더 멀리 갈 수 있어요. 전기차는 보통 km/kWh 등 다른 단위를 쓰며, 실제 효율은 기온과 운전 조건에 따라 달라요."))
    );

    private ChatGuideAnswers() {}

    public static Guide find(String guideId) {
        Guide guide = ANSWERS.get(guideId);
        if (guide == null) throw new ApiException(HttpStatus.BAD_REQUEST, "CHAT_GUIDE_NOT_FOUND", "등록된 안내를 찾을 수 없습니다.");
        return guide;
    }
}
